import{bV as e,aL as t,u as r,G as o}from"./chunks/framework.C8THFwVE.js";const _=JSON.parse('{"title":"情绪词库","description":"","frontmatter":{"date":"2026-06-13T17:31:20.000Z","title":"情绪词库","permalink":"/heart/8ef6ff","categories":["心语角落"]},"headers":[],"relativePath":"19.心语角落/02.情绪词库.md","filePath":"19.心语角落/02.情绪词库.md"}'),i={name:"19.心语角落/02.情绪词库.md"};function n(l,a,h,s,d,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="情绪词库" tabindex="-1">情绪词库 <a class="header-anchor" href="#情绪词库" aria-label="Permalink to &quot;情绪词库&quot;">​</a></h1><p><strong>emm...荒废中，理论上不会再更新了</strong></p><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>人类几乎所有的情绪，都可以用以下七个字来概括：<strong>『喜』、『怒』、『哀』、『惧』、『恶』、『惊』、『奇』</strong></p><h4 id="因爱生恨" tabindex="-1">因爱生恨 <a class="header-anchor" href="#因爱生恨" aria-label="Permalink to &quot;因爱生恨&quot;">​</a></h4><p>被所爱之人或者期待能善待自己的人伤害了，因而引发了痛苦和愤怒，其根源是悲痛和震惊，但很快有衍生出了强烈的自尊，同时又可能带有倔强的意味。有些人还会有恐惧、害怕这种被抛弃的感觉。</p><p>关联：屈辱、愤恨</p><h4 id="空心感" tabindex="-1">空心感 <a class="header-anchor" href="#空心感" aria-label="Permalink to &quot;空心感&quot;">​</a></h4><p>一种感知到一切缺乏意义而产生的空虚，一种精神层面的瘫痪、无能为力，一方面让人瘫软无力，内心提不起劲做任何事，另一方面又让人坐立不安，迫切想逃，总结就是带着焦躁的空虚。</p><p>关联：无聊</p><h4 id="撒娇" tabindex="-1">撒娇 <a class="header-anchor" href="#撒娇" aria-label="Permalink to &quot;撒娇&quot;">​</a></h4><p>一种将他人的爱视为理所当然的情绪，我们依赖别人的帮助，而不觉得有感激的义务。这其实代表回归婴儿时期的宠爱和无条件照顾，这是关系稳固发展的粘合剂，象征着最深的依赖。</p><p>关联：慰藉、脆弱</p><h4 id="非解释不可的" tabindex="-1">非解释不可的 <a class="header-anchor" href="#非解释不可的" aria-label="Permalink to &quot;非解释不可的&quot;">​</a></h4><h4 id="愤怒" tabindex="-1">愤怒 <a class="header-anchor" href="#愤怒" aria-label="Permalink to &quot;愤怒&quot;">​</a></h4>',15)])])}const u=e(i,[["render",n]]);export{_ as __pageData,u as default};
